/*
 * A001300  Number of ways of making change for n cents using coins of 1, 5,
 *          10, 25, 50 cents.
 * https://oeis.org/A001300
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) counts partitions of n into parts {1, 5, 10, 25, 50}
 *            Generated by: 1/((1-x)*(1-x^5)*(1-x^10)*(1-x^25)*(1-x^50))
 * Range:     u8 n <= 99, u16 n <= 514, u32 n <= 8914, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n) {
    seq_t *dp = (seq_t *)malloc(((size_t)n + 1) * sizeof(seq_t));
    if (dp == NULL) return 0;
    
    for (idx_t i = 0; i <= n; i++) {
        dp[i] = 1;
    }
    
    for (idx_t i = 5; i <= n; i++) {
        dp[i] += dp[i - 5];
    }
    
    for (idx_t i = 10; i <= n; i++) {
        dp[i] += dp[i - 10];
    }
    
    for (idx_t i = 25; i <= n; i++) {
        dp[i] += dp[i - 25];
    }
    
    for (idx_t i = 50; i <= n; i++) {
        dp[i] += dp[i - 50];
    }
    
    seq_t result = dp[n];
    free(dp);
    return result;
}
